+  const store = bigStore(5000);
+  // reference: full stable sort, newest first
+  const all = store.listShipments();
+  const reference = (pred: (s: (typeof all)[number]) => boolean) =>
+    all.filter(pred).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
+
+  it('returns everything newest first without a limit', () => {
+    assert.equal(all.length, 5000);
+    for (let i = 1; i < all.length; i++) assert.ok(all[i - 1].createdAt >= all[i].createdAt);
+  });
+
+  for (const limit of [1, 50, 500, 4999, 5000, 9999]) {
+    it(`limit=${limit} equals the first ${limit} of the full sorted list (ties keep insertion order)`, () => {
+      const got = store.listShipments({ limit }).map((s) => s.id);
+      assert.deepEqual(got, reference(() => true).slice(0, limit).map((s) => s.id));
+    });
+  }
+
+  it('applies carrier and status filters before the limit', () => {
+    const got = store.listShipments({ carrier: 'ATP', status: 'picked_up', limit: 40 }).map((s) => s.id);
