+    assert.equal(want.length, 40);
+    assert.deepEqual(got, want.map((s) => s.id));
+  });
+
+  it('does not mutate the stored shipments or depend on previous calls', () => {
+    const first = store.listShipments({ limit: 50 }).map((s) => s.id);
